4|// pipeline/out/clean/<basename>.json.
5|import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
6|import { basename, join } from "node:path";
7|import { JSDOM } from "jsdom";
8|import { cleanSections } from "../core/clean";
9|import type { Judge } from "../core/clean";
10|import { readEpubSections } from "../core/epub-sections";
11|import { createCleanJudge } from "./clean-judge";
12|import { createMetaClient } from "./meta";
13|
14|function loadEnv(): void {
15|  try {
16|    if (typeof process.loadEnvFile === "function") process.loadEnvFile(".env.local");
17|  } catch {
18|    // No .env.local is fine; env may come from elsewhere.
19|  }
20|}
21|
22|async function main(): Promise<void> {
23|  loadEnv();
24|  const args = process.argv.slice(2);
25|  const file = args.find((a) => !a.startsWith("--")) ?? "";
26|  const noLlm = args.includes("--no-llm");
27|  if (file === "") throw new Error("usage: clean:epub <file.epub> [--no-llm]");
28|  const bytes = new Uint8Array(readFileSync(file));
29|  const { title, sections } = readEpubSections(bytes, (text, type) => {
30|    if (type === "text/html") return new JSDOM(text).window.document;
31|    return new JSDOM(text, { contentType: type }).window.document;
32|  });
33|  let judge: Judge | undefined;
34|  if (!noLlm) {
35|    const apiKey = process.env.META_API_KEY ?? "";
36|    if (apiKey === "") throw new Error("META_API_KEY is not set");
37|    judge = createCleanJudge(
38|      createMetaClient({ apiKey, model: process.env.CLEAN_MODEL ?? "muse-spark-1.3-contributor" }),
39|    );
40|  }
41|  const { chapters, report } = await cleanSections(title, sections, judge);
42|  if (chapters.length === 0) throw new Error("no chapters kept after cleaning");
43|  for (const chapter of chapters) {
44|    console.log(`keep: ${chapter.title} (${chapter.paragraphs.length} paragraphs)`);
45|  }
46|  const byRule = new Map<string, string[]>();
47|  for (const item of report.removed) {
48|    const list = byRule.get(item.rule) ?? [];
49|    list.push(item.sectionId);
50|    byRule.set(item.rule, list);
51|  }
52|  for (const [rule, ids] of [...byRule.entries()].sort()) {
53|    console.log(`removed ${rule}: ${ids.length} (${ids.join(", ")})`);
54|  }
55|  for (const flag of report.flagged) {
