221|    if (nonEmpty.length === 0) return null;
222|    const mine = new Set([normalizeTitle(deriveTitle(sec, bookTitle))]);
223|    const firstHead = sec.blocks.find((b) => b.heading);
224|    if (firstHead !== undefined) mine.add(normalizeTitle(firstHead.text));
