236|function isAdBlock(text: string): boolean {
237|  const t = text.trim();
238|  if (/\b\d+\s*s\./.test(t)) return true; // 6s., 3s. 6d.
239|  if (/\b\d+\s*s\.(?:\s*\d+\s*d\.)?\s*net\b/i.test(t)) return true; // 6s. net
240|  if (/^\s*net\s*\.?\s*$/i.test(t)) return true; // a whole block reading net
241|  if (/crown\s+8vo/i.test(t)) return true;
242|  if (/in\s+one\s+volume/i.test(t)) return true;
243|  if (/\bprice\b/i.test(t)) return true;
244|  if (/[—–]\s*[“"]/.test(t)) return true; // GLOBE.—"quote"
245|  if (/·|\bmacmillan\b|\blondon\b/i.test(t)) return true; // publisher address
246|  return false;
247|}
248|
249|// Rule 7: publisher ad bodies. `net` counts only price-adjacent or
250|// whole-block, never a bare word in prose.
251|export function ruleAdBody(sec: RawSection): { kind: string; reason: string } | null {
252|  if (sec.blocks.length === 0) return null;
253|  const hits = sec.blocks.filter((b) => isAdBlock(b.text)).length;
254|  if (hits / sec.blocks.length >= 0.3) {
255|    return { kind: "advertisement", reason: `${hits} of ${sec.blocks.length} blocks match ad tokens` };
256|  }
257|  return null;
258|}
259|
260|const CHAPTER_LABEL = /^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\b/i;
261|const BARE_NUMERAL = /^(?:[ivxlc]+|\d+)[.:]?$/i;
262|
263|// Rule 9: confident content skips keyword rules 5-7 and the LLM.
264|export function isConfident(sec: RawSection): boolean {
265|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
266|  if (heads.some((h) => CHAPTER_LABEL.test(h))) return true;
267|  if (sec.navLabel !== null && sec.navLabel.includes(":")) {
268|    if (heads.some((h) => BARE_NUMERAL.test(h))) return true;
269|  }
270|  return false;
271|}
272|
273|const END_MARK = /^(THE END|FINIS)\.?$/i;
274|const PRINTER_PATTERNS = [
275|  /^printed\s+(by|in)\b/i,
276|  /&\s*sons,?\s+limited/i,
277|  /r\.\s*&\s*r\.\s*clark/i,
278|  /limited,?\s+(london|edinburgh)\b/i,
279|];
280|
281|// Suffix length of the last kept section that rule 10 removes right after
282|// the judge runs: trailing printer lines, everything after THE END/FINIS,
283|// or the whole section when it sits past the END mark with no confident
284|// section after it.
285|export function deterministicTailOverlap(kept: RawSection[], lastIdx: number): number {
286|  const last = kept[lastIdx];
287|  if (last === undefined) return 0;
288|  const { endSec, endIdx } = findEndMark(kept);
289|  if (endSec !== -1 && lastIdx > endSec && !kept.slice(endSec + 1).some(isConfident)) {
290|    return last.blocks.length;
291|  }
292|  let overlap = 0;
293|  while (
294|    overlap < last.blocks.length &&
295|    PRINTER_PATTERNS.some((p) => p.test(last.blocks[last.blocks.length - 1 - overlap]?.text.trim() ?? ""))
296|  ) {
297|    overlap += 1;
298|  }
299|  if (endSec === lastIdx && endIdx < last.blocks.length - 1) {
300|    overlap = Math.max(overlap, last.blocks.length - 1 - endIdx);
301|  }
302|  return overlap;
303|}
304|
305|// Last THE END/FINIS mark across kept sections, if any.
306|function findEndMark(kept: RawSection[]): { endSec: number; endIdx: number } {
307|  let endSec = -1;
308|  let endIdx = -1;
309|  kept.forEach((sec, i) => {
310|    const idx = sec.blocks.map((b) => b.text.trim()).findLastIndex((t) => END_MARK.test(t));
311|    if (idx !== -1) {
312|      endSec = i;
313|      endIdx = idx;
314|    }
315|  });
316|  return { endSec, endIdx };
317|}
318|
319|// Rule 10: cut everything after the last THE END/FINIS mark in any kept
320|// section (Cottage Folk hides it mid-file with ad pages below), and drop
321|// every later section, unless a later section carries a confident chapter
322|// heading. Trailing printer lines go separately in every kept section.
323|// Printer lines hide mid-list too (a merged "Sussex." + printer line lands
324|// in a story the ad sections below used to follow). Sign-offs stay.
325|export function applyTailCut(kept: RawSection[], removed: RemovedItem[]): RawSection[] {
326|  const { endSec, endIdx } = findEndMark(kept);
327|  if (endSec === -1) return kept;
328|  const endSection = kept[endSec];
329|  if (endSection === undefined) return kept;
330|  const out = kept.slice(0, endSec + 1);
331|  if (endIdx < endSection.blocks.length - 1) {
332|    removed.push(removedFor(endSection, "tail-cut", "back_matter", "after THE END", [endIdx + 1, endSection.blocks.length - 1]));
333|    out[endSec] = { ...endSection, blocks: endSection.blocks.slice(0, endIdx + 1) };
334|  }
335|  const later = kept.slice(endSec + 1);
336|  if (later.some(isConfident)) return [...out, ...later];
337|  for (const sec of later) {
338|    removed.push(removedFor(sec, "tail-cut", "back_matter", "after THE END"));
339|  }
340|  return out;
341|}
342|
343|export function stripPrinterLines(sec: RawSection, removed: RemovedItem[]): RawSection {
344|  let end = sec.blocks.length;
345|  while (end > 0 && PRINTER_PATTERNS.some((p) => p.test(sec.blocks[end - 1]?.text.trim() ?? ""))) {
346|    end -= 1;
347|  }
348|  if (end === sec.blocks.length) return sec;
349|  removed.push(removedFor(sec, "tail-cut", "back_matter", "printer line", [end, sec.blocks.length - 1]));
350|  return { ...sec, blocks: sec.blocks.slice(0, end) };
351|}
352|
353|const IMAGE_PLACEHOLDER = /^(image|img|illus|illustration|fig)[ _-]?\d+[a-z]?$/i;
354|
355|// Rule 11: inside content, drop headings, illustration and image
356|// placeholders, Gutenberg page anchors, and a repeated chapter title in
357|// the first two body blocks (Cottage Folk "THE HOPPERS"). Oz chapters
358|// start with prose, so the duplicate-title drop never fires there.
359|export function toParagraphs(sec: RawSection, title: string): string[] {
360|  const normTitle = normalizeTitle(title);
361|  const body = sec.blocks.filter((b) => !b.heading);
362|  let skip = 0;
363|  if (normTitle.length > 0 && sec.blocks.some((b) => b.heading)) {
364|    for (const b of body.slice(0, 2)) {
365|      if (normalizeTitle(b.text) === normTitle) skip += 1;
366|      else break;
367|    }
368|  }
369|  return body
370|    .slice(skip)
371|    .filter(
372|      (b) =>
373|        !/^\[illustration/i.test(b.text.trim()) &&
374|        !IMAGE_PLACEHOLDER.test(b.text.trim()) &&
375|        !/^\[pg\s*\d+\]$/i.test(b.text.trim()),
376|    )
377|    .map((b) => b.text);
378|}

