251|export function ruleAdBody(sec: RawSection): { kind: string; reason: string } | null {
252|  if (sec.blocks.length === 0) return null;
253|  const hits = sec.blocks.filter((b) => isAdBlock(b.text)).length;
254|  if (hits / sec.blocks.length >= 0.3) {
