305|// Last THE END/FINIS mark across kept sections, if any.
306|function findEndMark(kept: RawSection[]): { endSec: number; endIdx: number } {
307|  let endSec = -1;
308|  let endIdx = -1;
309|  kept.forEach((sec, i) => {
310|    const idx = sec.blocks.map((b) => b.text.trim()).findLastIndex((t) => END_MARK.test(t));
