319|// Rule 10: cut everything after the last THE END/FINIS mark in any kept
320|// section (Cottage Folk hides it mid-file with ad pages below), and drop
321|// every later section, unless a later section carries a confident chapter
322|// heading. Trailing printer lines go separately in every kept section.
323|// Printer lines hide mid-list too (a merged "Sussex." + printer line lands
324|// in a story the ad sections below used to follow). Sign-offs stay.
325|export function applyTailCut(kept: RawSection[], removed: RemovedItem[]): RawSection[] {
326|  const { endSec, endIdx } = findEndMark(kept);
327|  if (endSec === -1) return kept;
328|  const endSection = kept[endSec];
329|  if (endSection === undefined) return kept;
330|  const out = kept.slice(0, endSec + 1);
331|  if (endIdx < endSection.blocks.length - 1) {
332|    removed.push(removedFor(endSection, "tail-cut", "back_matter", "after THE END", [endIdx + 1, endSection.blocks.length - 1]));
333|    out[endSec] = { ...endSection, blocks: endSection.blocks.slice(0, endIdx + 1) };
334|  }
335|  const later = kept.slice(endSec + 1);
336|  if (later.some(isConfident)) return [...out, ...later];
337|  for (const sec of later) {
338|    removed.push(removedFor(sec, "tail-cut", "back_matter", "after THE END"));
339|  }
340|  return out;
341|}
342|
343|export function stripPrinterLines(sec: RawSection, removed: RemovedItem[]): RawSection {
344|  let end = sec.blocks.length;
345|  while (end > 0 && PRINTER_PATTERNS.some((p) => p.test(sec.blocks[end - 1]?.text.trim() ?? ""))) {
346|    end -= 1;
347|  }
348|  if (end === sec.blocks.length) return sec;
349|  removed.push(removedFor(sec, "tail-cut", "back_matter", "printer line", [end, sec.blocks.length - 1]));
350|  return { ...sec, blocks: sec.blocks.slice(0, end) };
