362|  let skip = 0;
363|  if (normTitle.length > 0 && sec.blocks.some((b) => b.heading)) {
364|    for (const b of body.slice(0, 2)) {
365|      if (normalizeTitle(b.text) === normTitle) skip += 1;
366|      else break;
367|    }
368|  }
369|  return body
370|    .slice(skip)
371|    .filter(
372|      (b) =>
373|        !/^\[illustration/i.test(b.text.trim()) &&
374|        !IMAGE_PLACEHOLDER.test(b.text.trim()) &&
375|        !/^\[pg\s*\d+\]$/i.test(b.text.trim()),
