38|
39|describe("judge safety", () => {
40|  it("uncertain stays kept and flagged", async () => {
41|    const judge = fakeJudge((id) => ({ id, verdict: "uncertain", kind: "other", reason: "not sure" }));
42|    const { chapters, report } = await cleanSections("B", [tale("a", 10)], judge);
43|    expect(chapters.map((c) => c.title)).toEqual(["A Tale"]);
44|    expect(report.flagged.map((f) => f.sectionId)).toEqual(["a"]);
45|  });
46|
