49|      sections: [{ id: "ghost", verdict: "non_content", kind: "other", reason: "no such section" }],
50|      headCut: 0,
51|      tailCut: 0,
52|      model: "fake",
53|      promptTokens: 1,
54|      completionTokens: 1,
55|      cachedTokens: 0,
56|      costUsd: 0,
57|    });
58|    const { chapters, report } = await cleanSections("B", [tale("a", 10)], judge);
59|    expect(chapters.map((c) => c.title)).toEqual(["A Tale"]);
60|    expect(report.removed).toEqual([]);
61|  });
62|
