68|    expect(report.removed.map((r) => r.sectionId)).toContain("edge");
69|    expect(chapters).toHaveLength(2);
70|  });
71|
72|  it("long interior non_content stays kept and flagged", async () => {
73|    const judge = fakeJudge((id) =>
74|      id === "long"
75|        ? { id, verdict: "non_content", kind: "advertisement", reason: "x".repeat(200) }
76|        : content(id),
77|    );
78|    const { chapters, report } = await cleanSections("B", [tale("a", 10), tale("long", 2100), tale("c", 10)], judge);
